7	import org.springframework.samples.petclinic.rest.escalation.OwnerIdentityDuplicateException;
8	
9	/**
10	 * The single duplicate-detection step of {@code POST /api/owners}. Runs after {@link AssignHousehold}
11	 * (so the new owner's {@code householdId} is set) and before {@link SaveOwner}. Rejects the create
12	 * with a 409 via {@link OwnerIdentityDuplicateException} when the new owner's whole derived
13	 * {@code identityKey} equals an existing owner's.
14	 *
15	 * <p>This replaces the former separate telephone, email and household checks: all three are now
16	 * expressed through the one {@link OwnerIdentity} key. Because the normalized telephone is part of the
17	 * key, two members of the same household (same {@code householdId}) with different telephones have
18	 * different keys and are both allowed — only an exact full-key match is a duplicate. The new owner is
19	 * still unsaved, so it is not among the owners iterated here and cannot match itself.
20	 */
21	public class CheckOwnerIdentityUnique {
